## Why This Is Asked
Tests DP partitioning with a non-sum objective and reconstruction requirements.

## Key Concepts
- DP over partitions with dp[i][t]
- Precomputing max-min for all subarrays
- Path reconstruction via parent pointers

## Code Example
```javascript
function maxMinSubarrayVal(arr){
  const n = arr.length;
  const maxVal = Array.from({length:n}, ()=>Array(n).fill(0));
  const minVal = Array.from({length:n}, ()=>Array(n).fill(0));
  for(let i=0;i<n;i++){
    let curMax = arr[i], curMin = arr[i];
    for(let j=i;j<n;j++){
      curMax = Math.max(curMax, arr[j]);
      curMin = Math.min(curMin, arr[j]);
      maxVal[i][j] = curMax;
      minVal[i][j] = curMin;
    }
  }
  const val = (l,r)=> maxVal[l][r] - minVal[l][r];
  return val;
}

function bestPartition(arr, k){
  const n = arr.length;
  const val = maxMinSubarrayVal(arr);
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const parent = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for(let i=1;i<=n;i++) dp[i][1] = val(0,i-1);
  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<=i-1;j++){
        const cand = dp[j][t-1] + val(j, i-1);
        if(cand > dp[i][t]){ dp[i][t] = cand; parent[i][t]=j; }
      }
    }
  }
  // reconstruct
  let blocks = [];
  let i=n, t=k;
  while(t>0){
    const j = parent[i][t];
    blocks.push([j, i-1]);
    i = j; t--;
  }
  blocks.reverse();
  return {value: dp[n][k], blocks};
}
```

## Follow-up Questions
- How to optimize memory to O(nk)?
- Can you handle ties deterministically for block reconstruction?

## Why This Is Asked
Tests ability to model interval scheduling with a cap on concurrent starts, a common real-world constraint in job scheduling and ad campaigns.

## Key Concepts
- Weighted interval scheduling with a limit on number of intervals
- Preprocessing next[i] via binary search
- DP with reconstruction pointers for actual selection

## Code Example
```javascript
// Pseudocode sketch for dp and reconstruction
function maxProfitTasks(s, d, p, k) {
  const n = s.length;
  const idx = [...Array(n).keys()].sort((a,b)=> s[a]-s[b]);
  // reorder s,d,p by idx as needed; compute next[] with binary search
  const next = Array(n).fill(n);
  for (let i=0;i<n;i++) {
    let limit = s[i] + d[i] - 1;
    // binary search for first j with s[j] > limit
    let lo=i+1, hi=n; while (lo<hi){
      let mid=(lo+hi)>>1; if (s[mid] > limit) hi=mid; else lo=mid+1; }
    next[i] = lo;
  }
  const dp = Array.from({length:n+1}, ()=> Array(k+1).fill(0));
  const take = Array.from({length:n}, ()=> Array(k+1).fill(false));
  for (let i=n-1;i>=0;i--) {
    for (let t=1;t<=k;t++) {
      if (dp[i+1][t] >= p[i] + dp[next[i]][t-1]) {
        dp[i][t] = dp[i+1][t];
        take[i][t] = false;
      } else {
        dp[i][t] = p[i] + dp[next[i]][t-1];
        take[i][t] = true;
      }
    }
  }
  // reconstruction omitted for brevity
  return {profit: dp[0][k], take, next};
}
```

## Why This Is Asked
Tests ability to model partitioning with a simple per-block objective and reconstruct optimal cuts. It reveals DP formulation, range queries, and backtracking.

## Key Concepts
- Partition DP across two dimensions (prefix and blocks)
- Range maximum precomputation or on-the-fly tracking
- Backpointers for path reconstruction
- Time/space trade-offs and potential optimizations

## Code Example
```javascript
function minPartitionCostMax(A, m){
  const n = A.length;
  // precompute max for all ranges
  const rangeMax = Array.from({length: n}, () => Array(n).fill(0));
  for(let i=0;i<n;i++){
    let cur = 0;
    for(let j=i;j<n;j++){
      cur = Math.max(cur, A[j]);
      rangeMax[i][j] = cur;
    }
  }
  const dp = Array.from({length: n+1}, () => Array(m+1).fill(Infinity));
  const par = Array.from({length: n+1}, () => Array(m+1).fill(-1));
  dp[0][0] = 0;
  for(let i=1;i<=n;i++){
    for(let j=1;j<=Math.min(i,m);j++){
      for(let t=j-1; t<=i-1; t++){
        const val = dp[t][j-1] + rangeMax[t][i-1];
        if(val < dp[i][j]){
          dp[i][j] = val;
          par[i][j] = t;
        }
      }
    }
  }
  // reconstruct
  const cuts = [];
  let i = n, j = m;
  while(j>0){
    const t = par[i][j];
    cuts.push(i);
    i = t;
    j--;
  }
  cuts.reverse();
  return {cost: dp[n][m], partitions: cuts};
}
```

## Follow-up Questions
- How would you optimize to O(n m) time using monotonic queues?  
- How would you adapt if each chapter cost were max(A[t..i-1]) + c*(i-t)?

## Why This Is Asked
Tests partition DP with a subarray range cost, requiring precomputation of subarray extrema and careful reconstruction. It adds a different objective than prior questions by using (max-min) rather than a function of endpoints or a fixed multiplier. 

## Key Concepts
- DP over partitions with exact-k segments
- Subarray range queries (max-min) via precomputation
- Path reconstruction from parent pointers
- Time/space trade-offs for small to mid-size n

## Code Example
```javascript
function minCostPartition(A, k) {
  const n = A.length;
  const maxv = Array.from({length: n}, () => Array(n).fill(0));
  const minv = Array.from({length: n}, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    maxv[i][i] = A[i];
    minv[i][i] = A[i];
    for (let j = i + 1; j < n; j++) {
      maxv[i][j] = Math.max(maxv[i][j-1], A[j]);
      minv[i][j] = Math.min(minv[i][j-1], A[j]);
    }
  }
  const INF = 1e18;
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(INF));
  const par = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) dp[i][1] = (maxv[0][i-1]-minv[0][i-1]) * i, par[i][1] = 0;
  for (let t = 2; t <= k; t++) {
    for (let i = t; i <= n; i++) {
      for (let p = t-1; p <= i-1; p++) {
        const cost = (maxv[p][i-1]-minv[p][i-1]) * (i-p);
        if (dp[p][t-1] + cost < dp[i][t]) {
          dp[i][t] = dp[p][t-1] + cost;
          par[i][t] = p;
        }
      }
    }
  }
  let idx = n, rem = k, cuts = [];
  while (rem > 0) {
    const p = par[idx][rem];
    cuts.push([p, idx-1]);
    idx = p; rem--;
  }
  cuts.reverse();
  return {cost: dp[n][k], blocks: cuts};
}
```

## Why This Question Is Asked
This problem assesses your ability to handle non-trivial path constraints in dynamic programming, specifically exact turn counting. It also requires path reconstruction, reflecting real-world interview complexity where identifying a solution isn't sufficient—you must also provide the actual path.

## Key Concepts
- **4D DP state** capturing both position and path history: `(i, j, t, dir)` tracks where you are, how many turns you've made, and your incoming direction
- **Turn counting** via conditional transitions: staying in the same direction doesn't increment the turn count, while switching does
- **Backpointer-based reconstruction** stores the predecessor for each state, enabling full path recovery

## Code Example
```javascript
function maxPathWithKTurns(grid, k) {
  const n = grid.length, m = grid[0].length;
  const dp = Array.from({length: n}, () =>
    Array.from({length: m}, () =>
      Array.from({length: k + 1}, () => [-Infinity, -Infinity])
    )
  );
  dp[0][0][0][0] = dp[0][0][0][1] = grid[0][0];

  const parent = Array.from({length: n}, () =>
    Array.from({length: m}, () =>
      Array.from({length: k + 1}, () => [null, null])
    )
  );

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      for (let t = 0; t <= k; t++) {
        if (i === 0 && j === 0) continue;
        if (j > 0) {
          const fromRight = dp[i][j-1][t][0];
          const fromDown = t > 0 ? dp[i][j-1][t-1][1] : -Infinity;
          if (fromRight >= fromDown) {
            dp[i][j][t][0] = fromRight + grid[i][j];
            parent[i][j][t][0] = [i, j-1, t, 0];
          } else {
            dp[i][j][t][0] = fromDown + grid[i][j];
            parent[i][j][t][0] = [i, j-1, t-1, 1];
          }
        }
        if (i > 0) {
          const fromDown = dp[i-1][j][t][1];
          const fromRight = t > 0 ? dp[i-1][j][t-1][0] : -Infinity;
          if (fromDown >= fromRight) {
            dp[i][j][t][1] = fromDown + grid[i][j];
            parent[i][j][t][1] = [i-1, j, t, 1];
          } else {
            dp[i][j][t][1] = fromRight + grid[i][j];
            parent[i][j][t][1] = [i-1, j, t-1, 0];
          }
        }
      }
    }
  }

  const endDir = dp[n-1][m-1][k][0] >= dp[n-1][m-1][k][1] ? 0 : 1;
  const maxSum = dp[n-1][m-1][k][endDir];
  const path = [];
  let cur = [n-1, m-1, k, endDir];

  while (cur) {
    path.unshift([cur[0], cur[1]]);
    cur = parent[cur[0]][cur[1]][cur[2]][cur[3]];
  }

  return { sum: maxSum, path };
}
```

## Why This Is Asked
Tests real DP design with an extra state (discount used) and careful recurrence.

## Key Concepts
- 2D DP with a binary state (discount used or not)
- Transitions combine taking cost with/without discount
- Space optimization using rolling arrays

## Code Example
```javascript
function minCostWithDiscount(grid){
  const n = grid.length, m = grid[0].length;
  const INF = 1e15;
  let dp0 = new Array(m).fill(INF);
  let dp1 = new Array(m).fill(INF);
  dp0[0] = grid[0][0];
  dp1[0] = Math.floor(grid[0][0] / 2);
  for (let j = 1; j < m; j++) {
    dp0[j] = grid[0][j] + dp0[j-1];
    dp1[j] = Math.min(grid[0][j] + dp1[j-1], Math.floor(grid[0][j]/2) + dp0[j-1]);
  }
  for (let i = 1; i < n; i++) {
    dp0[0] += grid[i][0];
    dp1[0] = Math.min(grid[i][0] + dp1[0], Math.floor(grid[i][0]/2) + dp0[0-1]);
    for (let j = 1; j < m; j++) {
      const v = grid[i][j];
      dp1[j] = Math.min(v + Math.min(dp1[j], dp1[j-1]), Math.floor(v/2) + Math.min(dp0[j], dp0[j-1]));
      dp0[j] = v + Math.min(dp0[j], dp0[j-1]);
    }
  }
  return dp1[m-1];
}
```

